TEST = 'from __future__ import annotations\n\nfrom collections.abc import Iterator, Mapping\nfrom dataclasses import replace\nfrom typing import Any\n\nimport pytest\n\nimport test_continuation as existing\nfrom ibae.continuation import (\n    ContinuationCheckpoint,\n    ProgressClassification,\n    ProgressRecord,\n    observe_continuation_context,\n)\n\n\nclass _DescriptorMutatingBenchmark(Mapping[str, Any]):\n    """One-shot hostile mapping used to exercise benchmark callback isolation."""\n\n    def __getitem__(self, key: str) -> Any:\n        if key != "rank":\n            raise KeyError(key)\n        return "non_authoritative"\n\n    def __iter__(self) -> Iterator[str]:\n        return iter(("rank",))\n\n    def __len__(self) -> int:\n        return 1\n\n    def items(self):\n        original = ProgressRecord.classification\n\n        def forged_progress(record: ProgressRecord):\n            # Restore before the late integrity check that made the old path\n            # exploitable, while reporting a forged authority value once.\n            ProgressRecord.classification = original\n            return ProgressClassification.MEASURABLE_PROGRESS\n\n        ProgressRecord.classification = property(forged_progress)\n        return {"rank": "non_authoritative"}.items()\n\n\ndef test_benchmark_callbacks_cannot_run_inside_governance_evaluation():\n    policy, _, _, _, policy_receipt, runtime, _, _, progress, state = (\n        existing._state_and_progress(progressing=False)\n    )\n    request = existing.ContinuationRequest.from_state(\n        state,\n        progress=progress,\n        requested_resources=policy.lease_schedule[0],\n        requester=existing.PrincipalAuthority.OPENAI_SUPERVISOR,\n        requester_authority=existing._authority(runtime),\n    )\n    try:\n        with pytest.raises(ValueError, match="engine integrity"):\n            existing.evaluate_continuation(\n                state,\n                request,\n                runtime_session=runtime,\n                policy=policy,\n                policy_receipt=policy_receipt,\n                progress=progress,\n                benchmark_observation=_DescriptorMutatingBenchmark(),\n            )\n    finally:\n        # If canonicalization itself aborts before the forged descriptor is\n        # consumed, restore the test process unconditionally.\n        current = ProgressRecord.classification\n        if isinstance(current, property):\n            # The original slot descriptor is available from the dataclass\n            # field declaration on a fresh class reload only, so force access\n            # through the hostile property to run its self-restoring getter.\n            _ = progress.classification\n    assert progress.classification is ProgressClassification.NO_PROGRESS\n\n\ndef test_checkpoint_rejects_structurally_forged_live_snapshot_fields():\n    policy, _, _, _, _, runtime, _, current, progress, state = (\n        existing._state_and_progress()\n    )\n    live = runtime.snapshot\n    forged = replace(live, logical_tick=live.logical_tick + 1)\n    with pytest.raises(ValueError, match="not the live native session state"):\n        ContinuationCheckpoint(\n            state=state,\n            policy=policy,\n            orchestration_state=current,\n            runtime_snapshot=forged,\n            progress=progress,\n        )\n\n    checkpoint = ContinuationCheckpoint(\n        state=state,\n        policy=policy,\n        orchestration_state=current,\n        runtime_snapshot=live,\n        progress=progress,\n    )\n    assert checkpoint.runtime_logical_tick == live.logical_tick\n\n\ndef test_progress_capacity_is_visible_and_impossible_recovery_is_suppressed():\n    policy, _, _, _, _, runtime, _, current, progress, state = (\n        existing._state_and_progress(progressing=False)\n    )\n    while state.progress_observations_remaining(policy) > 0:\n        state = observe_continuation_context(\n            state,\n            runtime_session=runtime,\n            policy=policy,\n            orchestration_state=current,\n            runtime_snapshot=runtime.snapshot,\n            progress=progress,\n        )\n\n    projection = state.compact_projection(policy)\n    assert projection["progress_observations_remaining"] == 0\n    assert projection["lease_requests_remaining"] > 0\n    assert projection["lease_schedule_slots_remaining"] > 0\n    assert "provide_objective_progress" not in projection["legal_recovery_actions"]\n\n    with pytest.raises(ValueError, match="progress history exceeds"):\n        observe_continuation_context(\n            state,\n            runtime_session=runtime,\n            policy=policy,\n            orchestration_state=current,\n            runtime_snapshot=runtime.snapshot,\n            progress=progress,\n        )\n'


def digest(path: str) -> str:
    return hashlib.sha256(Path(path).read_bytes()).hexdigest()


def main() -> None:
    subprocess.run(["git", "merge-base", "--is-ancestor", EXPECTED_HEAD, "HEAD"], check=True)
    for path, expected in EXPECTED.items():
        actual = digest(path)
        if actual != expected:
            raise SystemExit(f"refusing repair: {path} drifted: {actual} != {expected}")
    subprocess.run(["patch", "-p0", "--batch", "--forward"], input=PATCH, text=True, check=True)
    Path("tests/test_continuation_exact_head_regressions.py").write_text(TEST, encoding="utf-8")


if __name__ == "__main__":
    main()
